import { RoxyLuckPillars as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyLuckPillarsProps = ComponentProps<typeof Element>;

export function RoxyLuckPillars(props: RoxyLuckPillarsProps) {
	return <Element {...props} />;
}

export default RoxyLuckPillars;
